'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs/promises'),path=require('node:path'),os=require('node:os');
const {openConnection}=require('../src/utils/salesRepository');
const {createPokemonLocalCatalog}=require('../src/utils/pokemonLocalCatalog');
const {createPokemonBundleInstall}=require('../src/utils/pokemonBundleInstall');
async function fixture(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'bundle-install-')),file=path.join(root,'db.sqlite');await fs.writeFile(file,'');const connect=()=>openConnection(file),db=await connect();try{await db.exec('CREATE TABLE card_cache(id TEXT PRIMARY KEY,name TEXT,printed_name TEXT,supertype TEXT,subtypes TEXT,types TEXT,rarity TEXT,set_id TEXT,set_name TEXT,number TEXT,image_url TEXT,game TEXT,language TEXT,available_printings TEXT,price_trend REAL)');}finally{await db.close();}t.after(()=>fs.rm(root,{recursive:true,force:true}));const snapshot={commit:'a'.repeat(40),language:'en',sets:[{id:'example',name:'Example',serie:{id:'physical',name:'Physical'}}],cards:[{id:'example-1',localId:'1',name:'Example card',category:'Pokemon',set:{id:'example'}}]};const store=createPokemonLocalCatalog({connect});let clock=0,loads=0;const install=createPokemonBundleInstall({store,now:()=>clock,loadSnapshot:async()=>{loads++;return snapshot;}});return {connect,store,install,snapshot,loads:()=>loads,advance:()=>{clock=600001;}};}
test('preview does not import, and confirmation is mandatory',async t=>{const f=await fixture(t),preview=await f.install.preview({commit:f.snapshot.commit});assert.equal(preview.language,'en');assert.equal(preview.cardCount,1);assert.equal(await f.store.status('en'),null);assert.throws(()=>f.install.apply({previewId:preview.previewId,confirmed:false}),error=>error.code==='CATALOG_CONFIRMATION_REQUIRED');assert.throws(()=>f.install.apply({previewId:'wrong',confirmed:true}),error=>error.code==='CATALOG_PREVIEW_INVALID');});
test('the approved in-memory snapshot is installed without reloading changed staged data or clearing prices',async t=>{const f=await fixture(t),preview=await f.install.preview({commit:f.snapshot.commit});const db=await f.connect();try{await db.run("INSERT INTO card_cache(id,name,printed_name,game,language,price_trend) VALUES('tcgdex-en-example-1','Existing','Existing','pokemon','English',111.25)");}finally{await db.close();}f.snapshot.cards[0].name='Changed after preview';assert.equal(f.install.apply({previewId:preview.previewId,confirmed:true}).running,true);assert.throws(()=>f.install.apply({previewId:preview.previewId,confirmed:true}),error=>error.code==='CATALOG_BUSY');const result=await f.install.waitForIdle();assert.equal(result.job.phase,'done');assert.equal(f.loads(),1);const card=await f.store.getCard('tcgdex-en-example-1');assert.equal(card.name,'Example card');assert.equal(card.price_trend,111.25);});
test('expired previews cannot import',async t=>{const f=await fixture(t),preview=await f.install.preview({commit:f.snapshot.commit});f.advance();assert.throws(()=>f.install.apply({previewId:preview.previewId,confirmed:true}),error=>error.code==='CATALOG_PREVIEW_EXPIRED');assert.equal(await f.store.status('en'),null);});
test('unapproved paths and URLs are not accepted as preview inputs',async t=>{const f=await fixture(t);await assert.rejects(f.install.preview({commit:f.snapshot.commit,directory:'/other'}),error=>error.code==='INVALID_CATALOG_REQUEST');await assert.rejects(f.install.preview({commit:f.snapshot.commit,url:'https://example.invalid'}),error=>error.code==='INVALID_CATALOG_REQUEST');assert.equal(f.loads(),0);});
test('import failures roll back instead of activating a conflicting identity',async t=>{const f=await fixture(t),db=await f.connect();try{await db.run("INSERT INTO card_cache(id,name,game,language) VALUES('tcgdex-en-example-1','Existing other game','mtg','English')");}finally{await db.close();}const preview=await f.install.preview({commit:f.snapshot.commit});f.install.apply({previewId:preview.previewId,confirmed:true});const result=await f.install.waitForIdle();assert.equal(result.job.phase,'failed');assert.equal(await f.store.status('en'),null);});
